1	import type { Meta, StoryObj } from "@storybook/react-vite";
2	import { forwardRef, type AnchorHTMLAttributes } from "react";
3	import { TextLink } from "./TextLink";
4	import { BodyText } from "../Text";
5	
6	const meta = {
7	  title: "Text/TextLink",
8	  component: TextLink,
9	  parameters: { layout: "centered" },
10	  tags: ["autodocs"],
11	  argTypes: {
12	    children: { control: "text" },
13	    href: { control: "text" },
14	    asChild: { control: "boolean" },
15	  },
16	} satisfies Meta<typeof TextLink>;
17	
18	export default meta;
19	type Story = StoryObj<typeof meta>;
20	
21	export const Default: Story = {
22	  args: {
23	    href: "#",
24	    children: "Read the changelog",
25	  },
26	};
27	
28	/** Stands in for Next.js `Link`: a component that renders its own `<a>` and forwards the ref. */
29	const RouterLink = forwardRef<
30	  HTMLAnchorElement,
31	  AnchorHTMLAttributes<HTMLAnchorElement>
32	>((props, ref) => <a ref={ref} {...props} />);
33	RouterLink.displayName = "RouterLink";
34	
35	export const WithAsChild: Story = {
36	  name: "asChild with a router link",
37	  render: () => (
38	    <TextLink asChild>
39	      <RouterLink href="#changelog">Changelog</RouterLink>
40	    </TextLink>
41	  ),
42	};
43	
44	export const InlineSentence: Story = {
45	  name: "Inline in sentence",
46	  render: () => (
47	    <BodyText>
48	      Learn more about our{" "}
49	      <TextLink href="#">design principles</TextLink> in the documentation.
50	    </BodyText>
51	  ),
52	};
